import{j as e,C as i,S as t,a as n,L as a}from"./index-BkJm9h22.js";function c(){return e.jsx("section",{style:{background:i.cream,padding:typeof window<"u"&&window.innerWidth<=768?"60px 16px":"80px 24px",paddingTop:typeof window<"u"&&window.innerWidth<=768?80:100},children:e.jsxs("div",{style:{maxWidth:800,margin:"0 auto"},children:[e.jsx(t,{tag:"Legal",tagColor:i.navy,title:"Privacy Policy",desc:"How Northern Birch Credit Union collects, uses, and protects your personal information under PIPEDA."}),[{t:"Our Commitment to Privacy",p:"Northern Birch Credit Union Limited ('Northern Birch', 'we', 'us') is committed to protecting the privacy and confidentiality of your personal information. This policy describes how we collect, use, disclose, and safeguard personal information in accordance with the Personal Information Protection and Electronic Documents Act (PIPEDA) and applicable provincial privacy legislation."},{t:"Information We Collect",p:"We collect personal information necessary to provide financial and insurance services, including: name, date of birth, address, phone number, email, Social Insurance Number (for tax reporting), employment and income information, financial information (assets, liabilities, credit history), health information (for insurance underwriting, with your consent), transaction history, and digital identifiers (IP address, device information, cookies)."},{t:"How We Use Your Information",p:"We use your personal information to: open and manage your accounts; process transactions and provide banking services; assess eligibility for credit, insurance, and investment products; comply with legal and regulatory obligations (FSRA, FINTRAC, CRA); prevent fraud and money laundering; improve our products and services; communicate about your accounts and relevant offers (with your consent). We will not use your information for purposes beyond what is described without your consent."},{t:"Sharing with Insurance Partners",p:"When you request insurance quotes or purchase insurance products, we share the minimum necessary information with our insurance manufacturing partners: The Personal Insurance Company (Desjardins), CUMIS (Co-operators), and Manulife Financial. These partners are bound by their own privacy policies and PIPEDA obligations. We obtain your consent before sharing health or sensitive information for insurance underwriting."},{t:"Your Rights Under PIPEDA",p:"You have the right to: access your personal information held by Northern Birch; request correction of inaccurate information; withdraw consent for non-essential uses (marketing, insurance referrals); file a complaint with our Privacy Officer or the Office of the Privacy Commissioner of Canada. To exercise these rights, contact our Privacy Officer at privacy@northernbirchcu.com or visit any branch."},{t:"Insurance Marketing Opt-Out",p:"You may opt out of insurance-related marketing communications at any time. This will not affect your existing banking relationship or any active insurance policies. To opt out, contact your branch, email privacy@northernbirchcu.com, or adjust your preferences in online banking settings."},{t:"Service Providers and Data Outside Canada",p:"Some information you submit through this website — appointment requests, claim requests and referrals — is processed and stored by service providers located outside Canada, including in the United States. While it is in another country it is subject to that country's laws, and may be accessible to its courts, law enforcement and national security authorities. We share only what the form collects, and only for the purpose stated at the point of collection. If you would rather not have your information handled this way, call us at 416-465-4659 or visit a branch and we will take your request in person."},{t:"Data Retention",p:"We retain your personal information for as long as necessary to provide services and comply with legal obligations. Financial records are retained for a minimum of 7 years as required by the Income Tax Act and FINTRAC regulations. Insurance records are retained for the life of the policy plus 7 years."},{t:"Data Security",p:"We protect your information using industry-standard security measures including SSL/TLS encryption, multi-factor authentication, firewalls, intrusion detection systems, and regular security audits. Our core banking platform (Celero/CGI) meets the security standards required by our regulator, the Financial Services Regulatory Authority of Ontario (FSRA)."},{t:"Cookies and Digital Tracking",p:"Our website uses essential cookies for functionality and analytics cookies to improve user experience. You can manage cookie preferences through your browser settings. We do not sell personal information to third parties for advertising purposes."},{t:"Contact",p:"Privacy Officer, Northern Birch Credit Union Limited, 4 Credit Union Drive, North York, Ontario M4A 2N8. Email: privacy@northernbirchcu.com. Phone: 416-465-4659. Office of the Privacy Commissioner of Canada: 1-800-282-1376 or www.priv.gc.ca."}].map((r,o)=>e.jsxs("div",{style:{marginBottom:24},children:[e.jsx("h3",{style:{fontFamily:n,fontSize:17,color:i.navy,margin:"0 0 8px",fontWeight:700},children:r.t}),e.jsx("p",{style:{fontFamily:n,fontSize:14,color:"#666",lineHeight:1.8,margin:0},children:e.jsx(a,{text:r.p})})]},o)),e.jsx("p",{style:{fontFamily:n,fontSize:12,color:"#707070",marginTop:32},children:"Last updated: March 2026. Northern Birch Credit Union Limited is regulated by the Financial Services Regulatory Authority of Ontario (FSRA)."})]})})}export{c as default};
